import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };
const refused = (o: any) => assert.equal(o.ok, false);

test('submit validates maxTries and duplicates', async () => {
  const h = await createHost();
  refused(await h.submit('a', 0));
  refused(await h.submit('a', 4));
  refused(await h.submit('a', 7));
  refused(await h.submit('a', -1));
  assert.equal(await h.job('a'), null);
  assert.deepEqual(await h.submit('a', 2), ok);
  refused(await h.submit('a', 2));
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 0, maxTries: 2 });
});

test('unknown job is refused', async () => {
  const h = await createHost();
  for (const m of ['claim', 'succeed', 'fail', 'lost', 'cancel'] as const) refused(await h[m]('x'));
  assert.equal(await h.job('x'), null);
});

test('retries until exhausted', async () => {
  const h = await createHost();
  await h.submit('a', 2);
  assert.deepEqual(await h.claim('a'), ok);
  refused(await h.claim('a'));
  assert.deepEqual(await h.fail('a'), ok);
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 1, maxTries: 2 });
  await h.claim('a');
  assert.deepEqual(await h.lost('a'), ok);
  assert.deepEqual(await h.job('a'), { status: 'failed', tries: 2, maxTries: 2 });
  refused(await h.claim('a'));
  refused(await h.fail('a'));
  refused(await h.cancel('a'));
});

test('cancel paths', async () => {
  const h = await createHost();
  await h.submit('q', 1);
  refused(await h.succeed('q'));
  assert.deepEqual(await h.cancel('q'), ok);
  assert.equal((await h.job('q'))!.status, 'cancelled');
  await h.submit('r', 1); await h.claim('r');
  assert.deepEqual(await h.cancel('r'), ok);
  assert.equal((await h.job('r'))!.status, 'cancelling');
  refused(await h.cancel('r'));
  refused(await h.claim('r'));
  await h.succeed('r');
  assert.deepEqual(await h.job('r'), { status: 'succeeded', tries: 1, maxTries: 1 });
  await h.submit('s', 3); await h.claim('s'); await h.cancel('s');
  await h.lost('s');
  assert.deepEqual(await h.job('s'), { status: 'cancelled', tries: 1, maxTries: 3 });
});

